import{_ as o,c as t,o as d,ae as r}from"./chunks/framework.DYBsrYGD.js";const h=JSON.parse('{"title":"Vue 2 响应式原理","description":"","frontmatter":{},"headers":[],"relativePath":"框架和类库/Vue2/Vue2/响应式原理.md","filePath":"框架和类库/Vue2/Vue2/响应式原理.md"}'),a={name:"框架和类库/Vue2/Vue2/响应式原理.md"};function c(n,e,s,g,i,l){return d(),t("div",null,[...e[0]||(e[0]=[r('<h1 id="vue-2-响应式原理" tabindex="-1">Vue 2 响应式原理 <a class="header-anchor" href="#vue-2-响应式原理" aria-label="Permalink to &quot;Vue 2 响应式原理&quot;">​</a></h1><blockquote><p>与 Vue 3 的对照见：<a href="./../../Vue2与Vue3对比/响应式对比.html">Vue2与Vue3对比/响应式对比.md</a></p></blockquote><h2 id="_1-数据代理" tabindex="-1">1. 数据代理 <a class="header-anchor" href="#_1-数据代理" aria-label="Permalink to &quot;1. 数据代理&quot;">​</a></h2><p><strong>总结</strong>：把 <code>data</code> / <code>props</code> / <code>methods</code> 等挂到 <code>vm</code> 上，通过 <code>this.xxx</code> 访问更方便。</p><p><strong>要点</strong>：遍历 <code>data</code> 的属性，用 <strong><code>Object.defineProperty</code></strong> 在 <code>vm</code> 上定义同名访问器，<code>get</code> / <code>set</code> 实际读写的是原始 <code>data</code>。</p><h2 id="_2-数据劫持-响应式" tabindex="-1">2. 数据劫持（响应式） <a class="header-anchor" href="#_2-数据劫持-响应式" aria-label="Permalink to &quot;2. 数据劫持（响应式）&quot;">​</a></h2><p><strong>总结</strong>：把 <code>data</code> 里每个属性变成「带依赖收集与派发更新」的响应式属性。</p><p><strong>要点</strong>：</p><ul><li>每个属性对应一个 <strong><code>dep</code></strong>（依赖管理器）。</li><li><strong><code>get</code></strong>：返回属性值，并执行 <strong><code>dep.depend()</code></strong>，建立 <strong>dep ↔ watcher</strong> 的关联。</li><li><strong><code>set</code></strong>：同步更新值，并执行 <strong><code>dep.notify()</code></strong>，通知相关 <strong><code>watcher</code></strong> 把<strong>更新视图</strong>的逻辑放入异步队列（数据同步变，DOM 更新异步）。</li></ul><h2 id="_3-首次渲染" tabindex="-1">3. 首次渲染 <a class="header-anchor" href="#_3-首次渲染" aria-label="Permalink to &quot;3. 首次渲染&quot;">​</a></h2><p><strong>总结</strong>：解析模板 → 生成虚拟 DOM → 渲染真实 DOM；过程中<strong>读数据会触发 <code>get</code></strong>，从而<strong>建立</strong>上述响应式关联。</p><p><strong>要点</strong>：初始化时创建 <strong><code>Watcher</code></strong>，渲染中读取表达式 → 触发代理 <code>get</code> → 触发劫持 <code>get</code> → <strong><code>dep.depend()</code></strong> 完成依赖收集。</p><h2 id="_4-更新时" tabindex="-1">4. 更新时 <a class="header-anchor" href="#_4-更新时" aria-label="Permalink to &quot;4. 更新时&quot;">​</a></h2><p>修改 <code>data</code> → 触发代理 <code>set</code> → 触发劫持 <code>set</code> → <strong><code>dep.notify()</code></strong> → 遍历 watcher → 调度视图更新（常配合 <strong><code>nextTick</code></strong> 理解更新时机）。</p>',14)])])}const u=o(a,[["render",c]]);export{h as __pageData,u as default};
